import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Keynote: State of the Cephalopod - Sage Weil, Co-Creator, Chief Architect & Ceph Project Leader","description":"","frontmatter":{"title":"Keynote: State of the Cephalopod - Sage Weil, Co-Creator, Chief Architect & Ceph Project Leader","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Scalability","Performance Optimization","Community Development"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynote_-_State_of_the_Cephalopod_-_Sage_Weil_Co-Creator_Chief_Architect_Ceph_Project_Leader.md","filePath":"posts/2019/Keynote_-_State_of_the_Cephalopod_-_Sage_Weil_Co-Creator_Chief_Architect_Ceph_Project_Leader.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Keynote_-_State_of_the_Cephalopod_-_Sage_Weil_Co-Creator_Chief_Architect_Ceph_Project_Leader.md"};function p(s,e,i,_,l,C){return o(),r("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： CephCon 2023 开幕式及Nautilus版本介绍</p><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>会议地点</strong>： 巴塞罗那</p><p><strong>参会人员</strong>： Ceph社区成员、赞助商、Linux Foundation代表等</p><p><strong>会议内容</strong>：</p><p><strong>一、会议开场</strong></p><ol><li><strong>致谢</strong>： Sage Weil（Red Hat Ceph项目负责人）感谢所有赞助商、Ceph基金会、Linux Foundation以及程序委员会成员对本次会议的支持。</li><li><strong>Ceph基金会介绍</strong>： Sage介绍了Ceph基金会，该基金会成立六个月前，旨在支持Ceph项目和社区，拥有31个成员组织。</li><li><strong>CephCon历史回顾</strong>： Sage回顾了CephCon的历史，从2004年的OSD I会议到今天的CephCon，Ceph项目不断发展壮大。</li><li><strong>会议反馈</strong>： Sage鼓励参会者提供对会议的反馈，包括喜欢什么、不喜欢什么，以及任何问题。</li></ol><p><strong>二、Ceph介绍</strong></p><ol><li><strong>Ceph定义</strong>： Ceph是一个统一的存储系统，提供对象存储（兼容S3和Swift）、块存储和分布式文件系统等功能。</li><li><strong>Ceph特点</strong>： 开源、可靠性（无单点故障）、可扩展性（在线扩展或缩减）。</li><li><strong>Ceph社区优先事项</strong>： 提高可用性和管理性、支持与Kubernetes集成、支持多站点和混合云部署、性能优化、保证质量和稳定性。</li></ol><p><strong>三、Nautilus版本介绍</strong></p><ol><li><strong>Nautilus版本特点</strong>： 新的仪表盘、Orchestrator API、Rook、Ceph容器项目、Rados Gateway、性能优化（Blue Store、RocksDB、Rados Gateway）。</li><li><strong>Ceph性能优化</strong>： Project Crimson（重写Ceph I/O路径）。</li></ol><p><strong>四、未来计划</strong></p><ol><li><strong>Ceph性能优化</strong>： Project Crimson。</li><li><strong>Ceph社区优先事项</strong>： 保证质量、提高可用性和管理性、支持与Kubernetes集成、支持多站点和混合云部署、性能优化。</li></ol><p><strong>五、结束语</strong></p><p>Sage感谢参会者的到来，并欢迎他们参加CephCon 2023。</p><p><strong>后续行动计划</strong>：</p><ol><li>收集参会者对会议的反馈。</li><li>推进Ceph项目的开发。</li><li>支持Ceph社区的活动。</li></ol>',18)])])}const c=t(n,[["render",p]]);export{g as __pageData,c as default};
